if __name__ == "__main__":
    jobs = []
    for hid, subjects in S.items():
        for i, subject in enumerate(subjects, 1):
            jobs.append({"id": f"{hid}--page{i}", "subject": subject, "seed": 1000 + len(jobs)})
    json.dump(jobs, open(sys.argv[1], "w", encoding="utf-8"), indent=0)
    print(len(S), "holidays", len(jobs), "pages")
